import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    apples = [0] + [int(x) for x in input_data[1:N+1]]

    adj = [[] for _ in range(N + 1)]
    idx = N + 1
    for _ in range(N - 1):
        u = int(input_data[idx])
        v = int(input_data[idx+1])
        idx += 2
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (N + 1)
    children = [[] for _ in range(N + 1)]

    def dfs_build(u, p):
        parent[u] = p
        for v in adj[u]:
            if v != p:
                children[u].append(v)
                dfs_build(v, u)

    dfs_build(1, 0)

    def get_subtree_size(u, included):
        size = 1
        for v in children[u]:
            if (included & (1 << (v - 1))):
                size += get_subtree_size(v, included)
        return size

    max_score = -float('inf')

    for mask in range(1, 1 << N):
        if not (mask & 1):
            continue

        valid = True
        for i in range(N):
            if (mask & (1 << i)):
                u = i + 1
                p = parent[u]
                if p != 0 and not (mask & (1 << (p - 1))):
                    valid = False
                    break
        if not valid:
            continue

        total_apples = 0
        sub_costs = 0
        for i in range(N):
            if (mask & (1 << i)):
                u = i + 1
                total_apples += apples[u]
                if u != 1:
                    sub_costs += get_subtree_size(u, mask)

        score = total_apples - sub_costs
        if score > max_score:
            max_score = score

    print(max_score)

if __name__ == '__main__':
    solve()
